package org.apache.commons.jxpath.ri.model.jdom;

import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.model.NodeIterator;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.ri.model.jxpath.NodePointer;
import org.jdom.Attribute;
import org.jdom.Element;
import org.jdom.Namespace;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.w3c.dom.Attribute;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class JDOMAttributeIterator_getNodePointer_TriageGen1Test {

    private NodePointer mockParent;

    @Before
    public void setUp() {
        mockParent = mock(NodePointer.class);
    }

    @Test
    public void testGetNodePointer_PositionZero_SetPositionFails() throws Exception {
        // To make setPosition(1) fail, we can provide an empty list if setPosition logic 
        // depends on attribute size, or use a spy.
        JDOMAttributeIterator iterator = new JDOMAttributeIterator(mockParent, null);

        // Using reflection to set position to 0
        setField(iterator, "position", 0);
        // Using reflection to set attributes to empty list
        setField(iterator, "attributes", new ArrayList<Attribute>());

        // In JDOMAttributeIterator, setPosition(1) likely returns false if index 0 doesn't exist
        NodePointer result = iterator.getNodePointer();
        assertNull(result);
    }

    @Test
    public void testGetNodePointer_PositionZero_SetPositionSucceeds() throws Exception {
        Attribute mockAttr = mock(Attribute.class);
        List<Attribute> attributes = new ArrayList<>();
        attributes.add(mockAttr);

        JDOMAttributeIterator iterator = new JDOMAttributeIterator(mockParent, null);
        setField(iterator, "position", 0);
        setField(iterator, "attributes", attributes);
        setField(iterator, "parent", mockParent);

        // Logic: position is 0 -> setPosition(1) -> position becomes 1 -> position becomes 0
        // index = 0 - 1 = -1 -> index = 0
        NodePointer result = iterator.getNodePointer();
        assertNotNull(result);
    }

    @Test
    public void testGetNodePointer_PositionPositive_IndexCalculation() throws Exception {
        Attribute mockAttr = mock(Attribute.class);
        List<Attribute> attributes = new ArrayList<>();
        attributes.add(mockAttr);

        JDOMAttributeIterator iterator = new JDOMAttributeIterator(mockParent, null);
        setField(iterator, "position", 1); // position = 1
        setField(iterator, "attributes", attributes);
        setField(iterator, "parent", mockParent);

        // index = 1 - 1 = 0
        NodePointer result = iterator.getNodePointer();
        assertNotNull(result);
    }

    @Test
    public void testGetNodePointer_PositionNegative_IndexClampedToZero() throws Exception {
        Attribute mockAttr = mock(Attribute.class);
        List<Attribute> attributes = new ArrayList<>();
        attributes.add(mockAttr);

        JDOMAttributeIterator iterator = new JDOMAttributeIterator(mockParent, null);
        setField(iterator, "position", -5); // position = -5
        setField(iterator, "attributes", attributes);
        setField(iterator, "parent", mockParent);

        // index = -5 - 1 = -6 -> index = 0
        NodePointer result = iterator.getNodePointer();
        assertNotNull(result);
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }
}
